510	        prepared_registry_binding(&workspace, &target, &PackageId::parse("lib").unwrap())
511	    }
512	
513	    const CORP: &str = "[registries.corp]\nkind = \"npm\"\nurl = \"https://npm.corp.example/\"\n";
514	
515	    /// Only an npm override matching a configured npm registry is trusted.
516	    #[test]
517	    fn npm_override_must_match_a_configured_npm_registry() {
518	        assert!(npm_binding(CORP, "https://npm.corp.example/").is_ok());
519	        for untrusted in ["https://npm.evil.example/", "https://npm.corp.example/other/"] {
520	            assert!(
521	                matches!(
522	                    npm_binding(CORP, untrusted),
523	                    Err(GraphError::UntrustedNpmRegistry { .. })
524	                ),
525	                "{untrusted}"
526	            );
527	        }
528	        let cargo_kind = "[registries.corp]\nkind = \"cargo\"\nurl = \"https://npm.corp.example/\"\n";
529	        assert!(matches!(
530	            npm_binding(cargo_kind, "https://npm.corp.example/"),
531	            Err(GraphError::UntrustedNpmRegistry { .. })
532	        ));
533	    }
534	
535	    /// The scheme check runs first, so a cleartext approved host is unsafe, not untrusted.
536	    #[test]
537	    fn non_https_npm_override_is_unsafe_before_host_matching() {
538	        assert!(matches!(
539	            npm_binding(CORP, "http://npm.corp.example/"),
540	            Err(GraphError::UnsafeRegistryBinding { .. })
541	        ));
