 21	/// Credential-free, canonical registry routing. `endpoint` is populated only
 22	/// after parsing rejects userinfo, query, and fragments, so a later executor
 23	/// cannot recover credentials from this capability.
 24	#[derive(Debug)]
 25	pub(crate) struct PreparedRegistryBinding {
 26	    pub(crate) key: RegistryKey,
 27	    pub(crate) endpoint: Option<String>,
 28	    pub(crate) identity: RegistryBindingDigest,
 29	}
 30	
 31	/// Immutable, credential-free destination for Git effects. Its canonical
 32	/// digest is included in each tag-producing package fingerprint; the URL is
 33	/// retained only in the validated, non-serializable capability.
 34	#[derive(Clone, Debug, PartialEq, Eq)]
 35	pub(crate) struct PreparedGitRemote {
 36	    pub(crate) endpoint: String,
 37	    pub(crate) identity: SemanticInputDigest,
 38	    pub(crate) github_repository: Option<GitHubRepository>,
 39	}
 40	
 41	/// The single registry-trust validator: resolves `target`'s own registry key, rejects a
 42	/// non-https or credentialed URL, and rejects an npm `publishConfig.registry` override (package-
 43	/// controlled data) unless it matches a `url` on an npm-kind `[registries]` entry.
 44	pub(crate) fn prepared_registry_binding<R: CommandRunner, D: DependencyResolver>(
 45	    workspace: &Workspace<'_, R, D>,
 46	    target: &PublishTarget,
 47	    package: &PackageId,
 48	) -> Result<PreparedRegistryBinding, GraphError> {
 49	    let key = target.registry_key().ok_or_else(|| GraphError::ReleaseInvariant {
 50	        detail: format!("publish target `{}` has no registry key", target.config_str()),
 51	    })?;
 52	    // Built-in keys (pypi, nuget) need no [registries] entry; an unknown key still fails.
 53	    let builtin_unconfigured = builtin_registry_url(key.as_str()).is_some();
 54	    let configured_registry = match workspace.config.registries.get(&key) {
 55	        Some(registry) => Some(registry),
 56	        None if builtin_unconfigured => None,
 57	        None => {
 58	            return Err(GraphError::ReleaseInvariant {
 59	                detail: format!("unknown registry `{}`", key.as_str()),
 60	            })
 61	        }
 62	    };
 63	    if let Some(registry) = configured_registry.filter(|registry| Some(registry.kind) != target.ecosystem()) {
 64	        return Err(GraphError::ReleaseInvariant {
 65	            detail: format!(
 66	                "registry `{}` is configured for ecosystem `{}`, not `{}`",
 67	                key.as_str(),
 68	                registry.kind.prefix(),
 69	                target.ecosystem().map_or("none", |ecosystem| ecosystem.prefix())
 70	            ),
 71	        });
 72	    }
 73	    let explicit = target.registry_override();
 74	    let configured = configured_registry.and_then(|registry| registry.url.as_deref());
 75	    let raw = explicit.or(configured);
 76	    let Some(raw) = raw else {
 77	        return Ok(PreparedRegistryBinding {
 78	            key: key.clone(),
 79	            endpoint: None,
 80	            identity: RegistryBindingDigest::from_normalized_binding(key.as_str().as_bytes()),
 81	        });
 82	    };
 83	    let binding = canonical_registry_binding(key.as_str(), raw)?;
 84	    if explicit.is_some()
 85	        && matches!(target, PublishTarget::Npm { .. })
 86	        && !is_approved_npm_registry(workspace, &binding)
 87	    {
 88	        return Err(GraphError::UntrustedNpmRegistry {
 89	            package: package.clone(),
 90	            url: raw.to_owned(),
 91	        });
 92	    }
 93	    Ok(PreparedRegistryBinding {
 94	        key,
 95	        endpoint: Some(binding.endpoint()),
 96	        identity: binding.digest(),
 97	    })
 98	}
 99	
100	fn is_approved_npm_registry<R: CommandRunner, D: DependencyResolver>(
101	    workspace: &Workspace<'_, R, D>,
102	    binding: &RegistryBindingV1,
103	) -> bool {
104	    workspace.config.registries.values().any(|registry| {
105	        registry.kind == Ecosystem::Npm
106	            && registry
107	                .url
108	                .as_deref()
109	                .and_then(|url| canonical_registry_url(url).ok())
110	                .is_some_and(|approved| approved == *binding)
111	    })
112	}
113	
114	pub(crate) fn canonical_registry_binding(registry: &str, raw: &str) -> Result<RegistryBindingV1, GraphError> {
115	    canonical_registry_url(raw).map_err(|reason| GraphError::UnsafeRegistryBinding {
116	        registry: registry.to_string(),
117	        reason,
118	    })
119	}
