121	/// Maps a [`GitHubRepositoryParseError`] to a specific, static diagnostic
122	/// reason for [`GraphError::UnsafeGitRemote`], rather than discarding it
123	/// behind one generic message for every distinct parse failure.
124	fn github_repository_parse_error_reason(error: &GitHubRepositoryParseError) -> &'static str {
125	    match error {
126	        GitHubRepositoryParseError::MissingSeparator { .. } => "GitHub remote path must be in owner/repo form",
127	        GitHubRepositoryParseError::TooManyParts { .. } => "GitHub remote path has more than one `/`",
128	        GitHubRepositoryParseError::InvalidOwner { .. } => "GitHub owner name is invalid",
129	        GitHubRepositoryParseError::InvalidRepo { .. } => "GitHub repository name is invalid",
130	        GitHubRepositoryParseError::DotComponent { .. } => "GitHub owner or repository is a dot component",
131	        #[allow(unreachable_patterns)]
132	        _ => "GitHub owner or repository name is invalid",
133	    }
134	}
