189	pub(crate) fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
190	    let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
191	        let (host, path) =
192	            raw.strip_prefix("git@")
193	                .and_then(|value| value.split_once(':'))
194	                .ok_or(GraphError::UnsafeGitRemote {
195	                    reason: "invalid SSH remote syntax",
196	                })?;
197	        format!("ssh://git@{host}/{path}")
198	    } else {
199	        raw.to_string()
200	    };
201	    let parsed = url::Url::parse(&ssh_url).map_err(|error| GraphError::UnsafeGitRemote {
202	        reason: url_parse_error_reason(error),
203	    })?;
204	    if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
205	        return Err(GraphError::UnsafeGitRemote {
206	            reason: "URL must have an authority",
207	        });
208	    }
209	    if !matches!(parsed.scheme(), "https" | "ssh") {
210	        return Err(GraphError::UnsafeGitRemote {
211	            reason: "URL scheme must be HTTPS or SSH",
212	        });
213	    }
214	    if parsed.password().is_some() || parsed.query().is_some() || parsed.fragment().is_some() {
215	        return Err(GraphError::UnsafeGitRemote {
216	            reason: "credentials, query strings, and fragments are forbidden",
217	        });
218	    }
219	    if parsed.scheme() == "https" && !parsed.username().is_empty() {
220	        return Err(GraphError::UnsafeGitRemote {
221	            reason: "HTTPS userinfo is forbidden",
222	        });
223	    }
224	    if parsed.scheme() == "ssh" && parsed.username() != "git" {
225	        return Err(GraphError::UnsafeGitRemote {
226	            reason: "SSH remotes must use the git account",
227	        });
228	    }
229	    let host = parsed.host_str().expect("validated authority").to_ascii_lowercase();
230	    let mut components = parsed.path_segments().ok_or(GraphError::UnsafeGitRemote {
231	        reason: "remote path is invalid",
232	    })?;
233	    let owner = components
234	        .next()
235	        .filter(|value| !value.is_empty())
236	        .ok_or(GraphError::UnsafeGitRemote {
237	            reason: "remote path must name an owner and repository",
238	        })?;
239	    let repository = components
240	        .next()
241	        .filter(|value| !value.is_empty())
242	        .ok_or(GraphError::UnsafeGitRemote {
243	            reason: "remote path must name an owner and repository",
244	        })?;
245	    if components.next().is_some() || owner == "." || owner == ".." || repository == "." || repository == ".." {
246	        return Err(GraphError::UnsafeGitRemote {
247	            reason: "remote path must contain exactly an owner and repository",
248	        });
249	    }
250	    let repository = repository.strip_suffix(".git").unwrap_or(repository);
251	    if repository.is_empty() {
252	        return Err(GraphError::UnsafeGitRemote {
253	            reason: "repository name is empty",
254	        });
255	    }
256	    let port = parsed.port_or_known_default();
257	    let port_text = match (parsed.scheme(), port) {
258	        ("https", Some(443)) | ("ssh", Some(22)) | (_, None) => String::new(),
259	        (_, Some(port)) => format!(":{port}"),
260	    };
261	    let endpoint = match parsed.scheme() {
262	        "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
263	        "ssh" => format!("ssh://git@{host}{port_text}/{owner}/{repository}.git"),
264	        _ => unreachable!("scheme checked above"),
265	    };
266	    let mut transcript = CanonicalTranscript::semantic_input_v1();
267	    transcript.push_str("gitRemote.scheme", parsed.scheme());
268	    transcript.push_str("gitRemote.host", &host);
269	    transcript.push_str(
270	        "gitRemote.port",
271	        &port.map_or_else(String::new, |port| port.to_string()),
272	    );
273	    transcript.push_str("gitRemote.owner", owner);
274	    transcript.push_str("gitRemote.repository", repository);
275	    let github_repository = if host == "github.com" {
276	        Some(
277	            GitHubRepository::parse(&format!("{owner}/{repository}")).map_err(|error| GraphError::UnsafeGitRemote {
278	                reason: github_repository_parse_error_reason(&error),
279	            })?,
280	        )
281	    } else {
282	        None
283	    };
284	    Ok(PreparedGitRemote {
285	        endpoint,
286	        identity: SemanticInputDigest::from_transcript(&transcript),
287	        github_repository,
288	    })
289	}
