136	pub(crate) fn prepared_git_remote(root: &Path, runner: &dyn CommandRunner) -> Result<PreparedGitRemote, GraphError> {
137	    // A missing/unset `origin` is an answer this call interprets itself (into
138	    // `UnsafeGitRemote`), not an unexpected failure worth echoing git's own
139	    // "No such remote" to the terminal -- so this is a quiet probe.
140	    let output = runner.run_quiet(
141	        programs::GIT,
142	        &["remote", "get-url", "--push", programs::GIT_REMOTE],
143	        root,
144	        timeouts::LOCAL_GIT,
145	    )?;
146	    if output.exit_code != Some(0) {
147	        return Err(GraphError::UnsafeGitRemote {
148	            reason: "origin must have a push URL",
149	        });
150	    }
151	    canonical_git_remote(output.stdout.trim())
152	}
153	
154	/// `origin`'s canonical push URL, or `None` when `origin` has no push URL.
155	pub(crate) fn optional_git_remote(
156	    root: &Path,
157	    runner: &dyn CommandRunner,
158	) -> Result<Option<PreparedGitRemote>, GraphError> {
159	    // A repository with no `origin` is an expected, common case here (e.g.
160	    // before `init` adds one), not a failure -- probe quietly so git's own
161	    // "error: No such remote 'origin'" never reaches the terminal.
162	    let output = runner.run_quiet(
163	        programs::GIT,
164	        &["remote", "get-url", "--push", programs::GIT_REMOTE],
165	        root,
166	        timeouts::LOCAL_GIT,
167	    )?;
168	    if output.exit_code != Some(0) {
169	        return Ok(None);
170	    }
171	    canonical_git_remote(output.stdout.trim()).map(Some)
172	}
