 339	/// Renders `callisto.toml` from the answers: only answered intent and tag continuity, never defaults.
 340	pub fn render_config(facts: &InitFacts, answers: &InitAnswers) -> String {
 341	    use toml_edit::{value, Array, ArrayOfTables, DocumentMut, Item, Table};
 342	
 343	    let mut doc = DocumentMut::new();
 344	    if answers.versioning == Versioning::Fixed {
 345	        let members: Array = facts
 346	            .packages
 347	            .iter()
 348	            .filter(|package| !package.platform)
 349	            .map(|package| package.id.as_str())
 350	            .collect();
 351	        if !members.is_empty() {
 352	            let mut group = Table::new();
 353	            group["name"] = value("all");
 354	            group["members"] = value(members);
 355	            let mut groups = ArrayOfTables::new();
 356	            groups.push(group);
 357	            doc["fixed-group"] = Item::ArrayOfTables(groups);
 358	        }
 359	    }
 360	    let mut rules: BTreeMap<&str, Table> = BTreeMap::new();
 361	    for (package, template) in &facts.tag_templates {
 362	        rules.entry(package).or_default()["tag-template"] = value(template.as_str());
 363	    }
 364	    let product = answers
 365	        .binaries
 366	        .as_ref()
 367	        .and_then(|release| facts.packages.iter().find(|package| package.id == release.product));
 368	    if let Some(product) = product {
 369	        // Artifact slots derive only for a product that publishes to github-release.
 370	        let publish_to: Array = product
 371	            .publish_to
 372	            .iter()
 373	            .map(String::as_str)
 374	            .chain([PublishTarget::GitHubRelease.config_str()])
 375	            .collect();
 376	        rules.entry(&product.id).or_default()["publish-to"] = value(publish_to);
 377	    }
 378	    if !rules.is_empty() {
 379	        let mut tables = ArrayOfTables::new();
 380	        for (package, rule) in rules {
 381	            let mut table = Table::new();
 382	            table["match"] = value(package);
 383	            table.extend(rule);
 384	            tables.push(table);
 385	        }
 386	        doc["package"] = Item::ArrayOfTables(tables);
 387	    }
 388	    if let Some(release) = &answers.binaries {
 389	        let bin_names = product.map(|package| package.bin_names.as_slice()).unwrap_or_default();
 390	        let mut table = Table::new();
 391	        table["product-package"] = value(release.product.as_str());
 392	        table["forge-repository"] = value(release.forge_repository.as_slug());
 393	        let mut artifacts = ArrayOfTables::new();
 394	        for target in &release.targets {
 395	            for bin in bin_names {
 396	                let extension = if target.contains("windows") { "zip" } else { "tar.gz" };
 397	                let mut artifact = Table::new();
 398	                artifact["package"] = value(release.product.as_str());
 399	                artifact["target"] = value(target.as_str());
 400	                artifact["asset-name"] = value(format!("{bin}-{target}.{extension}"));
 401	                artifacts.push(artifact);
 402	            }
 403	        }
 404	        table["artifact"] = Item::ArrayOfTables(artifacts);
 405	        doc["release"] = Item::Table(table);
 406	    }
 407	    let body = doc.to_string();
 408	    if body.is_empty() {
 409	        CONFIG_HEADER.to_owned()
 410	    } else {
 411	        format!("{CONFIG_HEADER}\n{body}")
 412	    }
 413	}
