 439	/// Parses a forge repository answer, which the release plan requires to be `origin`'s GitHub repository.
 440	///
 441	/// # Errors
 442	///
 443	/// `value` is not a GitHub `owner/repo`, or is not `origin`'s.
 444	pub fn forge_repository(facts: &InitFacts, value: &str) -> Result<GitHubRepository, GraphError> {
 445	    let repository = GitHubRepository::parse(value.trim()).map_err(|error| GraphError::InitInvalidForgeRepository {
 446	        value: value.to_owned(),
 447	        reason: error.to_string(),
 448	    })?;
 449	    if facts.origin_repository.as_ref() != Some(&repository) {
 450	        return Err(GraphError::InitForgeRepositoryMismatch {
 451	            configured: repository.as_slug(),
 452	            origin: facts.origin.clone().unwrap_or_else(|| "none".to_owned()),
 453	        });
 454	    }
 455	    Ok(repository)
 456	}
