 636	/// Where [`default_branch`]'s branch name came from.
 637	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 638	pub enum DefaultBranchSource {
 639	    /// The local `refs/remotes/origin/HEAD` ref, set by `git clone` or `git remote set-head`.
 640	    OriginHead,
 641	    /// `git ls-remote --symref origin HEAD`, queried when the local ref above is unset.
 642	    RemoteHead,
 643	    /// The branch currently checked out: no remote reports a HEAD (e.g. `origin` is unset).
 644	    CurrentBranch,
 645	    /// No remote and no checked-out branch (e.g. a fresh repo with no commits): `main`.
 646	    Fallback,
 647	}
