 649	impl std::fmt::Display for DefaultBranchSource {
 650	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 651	        formatter.write_str(match self {
 652	            Self::OriginHead => "origin/HEAD",
 653	            Self::RemoteHead => "origin, queried live",
 654	            Self::CurrentBranch => "the current branch",
 655	            Self::Fallback => "fallback: none of the above resolved",
 656	        })
 657	    }
 658	}
