 694	/// The last path segment of a `refs/...` line, e.g. `refs/heads/trunk` -> `trunk`.
 695	fn last_ref_segment(reference: &str) -> Option<String> {
 696	    let branch = reference.trim().rsplit('/').next()?;
 697	    (!branch.is_empty()).then(|| branch.to_owned())
 698	}
 699	
 700	// A repository with no `origin/HEAD` (a fresh clone, or one built by hand, as in tests)
 701	// fails this on the common path, not just exceptionally.
 702	fn local_origin_head<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
 703	    let output = runner
 704	        .run_quiet(
 705	            programs::GIT,
 706	            &["symbolic-ref", "refs/remotes/origin/HEAD"],
 707	            root,
 708	            timeouts::LOCAL_GIT,
 709	        )
 710	        .ok()?;
 711	    if output.exit_code != Some(0) {
 712	        return None;
 713	    }
 714	    last_ref_segment(&output.stdout)
 715	}
 716	
 717	// A shallow or hand-built clone (or one `remote set-head` never ran on) has no local
 718	// `origin/HEAD`; asking the remote directly still resolves it without a fetch.
 719	fn remote_origin_head<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
 720	    let output = runner
 721	        .run_quiet(
 722	            programs::GIT,
 723	            &["ls-remote", "--symref", "origin", "HEAD"],
 724	            root,
 725	            timeouts::GIT_LS_REMOTE,
 726	        )
 727	        .ok()?;
 728	    if output.exit_code != Some(0) {
 729	        return None;
 730	    }
 731	    // Output line shape: "ref: refs/heads/<branch>\tHEAD".
 732	    output.stdout.lines().find_map(|line| {
 733	        let (target, name) = line.strip_prefix("ref: ")?.split_once('\t')?;
 734	        (name.trim() == "HEAD").then(|| last_ref_segment(target))?
 735	    })
 736	}
 737	
 738	// No remote at all (e.g. `init` in a repo built by hand with no `origin`): the branch
 739	// actually checked out is a better guess than a hardcoded `main`.
 740	fn current_branch<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
 741	    let output = runner
 742	        .run_quiet(
 743	            programs::GIT,
 744	            &["symbolic-ref", "--short", "HEAD"],
 745	            root,
 746	            timeouts::LOCAL_GIT,
 747	        )
 748	        .ok()?;
 749	    if output.exit_code != Some(0) {
 750	        return None;
 751	    }
 752	    let branch = output.stdout.trim();
 753	    (!branch.is_empty()).then(|| branch.to_owned())
 754	}
