 480	/// Files `init` writes, or would write under `--dry-run`: `callisto.toml`, `.changeset/README.md`
 481	/// unless it already exists, and the release workflow when `workflow` is `true`. Reads current
 482	/// disk state, so callers compute this before writing anything.
 483	pub fn init_files(root: &Path, workflow: bool) -> Vec<PathBuf> {
 484	    let mut files = vec![root.join("callisto.toml")];
 485	    if !root.join(".changeset/README.md").exists() {
 486	        files.push(root.join(".changeset/README.md"));
 487	    }
 488	    if workflow {
