 516	///
 517	/// # Errors
 518	///
 519	/// A directory or file write fails.
 520	pub fn write_changeset_readme(root: &Path, permit: &ApplyPermit) -> Result<(), GraphError> {
 521	    let readme = root.join(".changeset/README.md");
 522	    if readme.exists() {
