 530	/// `@changesets/cli` `config.json` keys callisto never reads, and the callisto.toml construct
 531	/// that replaces each one, when one exists.
 532	const CHANGESETS_CONFIG_KEYS: [(&str, Option<&str>); 6] = [
 533	    ("fixed", Some("[[fixed-group]]")),
 534	    ("linked", None),
 535	    ("ignore", None),
 536	    ("access", None),
 537	    ("baseBranch", None),
 538	    ("updateInternalDependencies", None),
