 541	/// Warns, per key, about every `.changeset/config.json` key callisto ignores.
 542	///
 543	/// callisto never translates this file; a present, unhonoured key is silently inert otherwise.
 544	/// Returns no diagnostics when the file is absent or is not a JSON object.
 545	pub fn changesets_config_diagnostics(root: &Path) -> Vec<Diagnostic> {
 546	    let path = root.join(".changeset/config.json");
 547	    let Ok(text) = std::fs::read_to_string(&path) else {
 548	        return Vec::new();
 549	    };
 550	    let Ok(serde_json::Value::Object(config)) = serde_json::from_str(&text) else {
 551	        return Vec::new();
 552	    };
 553	    CHANGESETS_CONFIG_KEYS
 554	        .iter()
 555	        .filter(|(key, _)| config.contains_key(*key))
 556	        .map(|(key, equivalent)| {
 557	            let message = match equivalent {
 558	                Some(equivalent) => {
 559	                    format!("`.changeset/config.json` key `{key}` is not honoured; use {equivalent} instead")
 560	                }
 561	                None => format!("`.changeset/config.json` key `{key}` is not honoured; callisto has no equivalent"),
 562	            };
 563	            Diagnostic {
 564	                code: DiagnosticCode::ChangesetsConfigKeyDropped,
 565	                severity: DiagnosticSeverity::Warning,
 566	                message,
 567	                package: None,
 568	                path: Some(path.clone()),
 569	                escalated_by: None,
 570	                governed_by: None,
 571	            }
 572	        })
 573	        .collect()
 574	}
