 597	/// Why `init` generates no workflow for a workspace.
 598	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 599	pub enum WorkflowUnsupported {
 600	    /// maturin platform builds have no generated build job.
 601	    Maturin,
 602	    /// Platform packages exist, but no package declares `napi.targets` to build them from.
