 606	impl std::fmt::Display for WorkflowUnsupported {
 607	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 608	        match self {
 609	            Self::Maturin => {
 610	                formatter.write_str("maturin platform builds (`[tool.maturin].targets`) are not generated")
 611	            }
 612	            Self::PlatformPackagesWithoutNapiTargets => {
 613	                formatter.write_str("the workspace has platform packages but no package declares `napi.targets`")
 614	            }
 615	        }
