 660	/// The repository's default branch and where that name came from.
 661	#[derive(Clone, Debug, PartialEq, Eq)]
 662	pub struct DefaultBranch {
 663	    pub name: String,
 664	    pub source: DefaultBranchSource,
 665	}
 666	
 667	/// The repository's default branch: local `origin/HEAD`, else a live query of `origin`,
 668	/// else the branch currently checked out, else `main`.
 669	pub fn default_branch<R: CommandRunner>(runner: &R, root: &Path) -> DefaultBranch {
 670	    if let Some(name) = local_origin_head(runner, root) {
 671	        return DefaultBranch {
 672	            name,
 673	            source: DefaultBranchSource::OriginHead,
 674	        };
 675	    }
 676	    if let Some(name) = remote_origin_head(runner, root) {
 677	        return DefaultBranch {
 678	            name,
 679	            source: DefaultBranchSource::RemoteHead,
 680	        };
 681	    }
 682	    if let Some(name) = current_branch(runner, root) {
 683	        return DefaultBranch {
 684	            name,
 685	            source: DefaultBranchSource::CurrentBranch,
 686	        };
 687	    }
 688	    DefaultBranch {
 689	        name: "main".to_owned(),
 690	        source: DefaultBranchSource::Fallback,
 691	    }
 692	}
