 789	// A raw string (not a `format!` template) for the same reason as `WORKFLOW_TEMPLATE`.
 790	const MATRIX_WORKFLOW_TEMPLATE: &str = r#"name: Release
 791	
 792	on:
 793	  push:
 794	    branches: [__BRANCH__]
 795	
 796	permissions: {}
 797	
 798	defaults:
 799	  run:
 800	    shell: bash
 801	
 802	jobs:
 803	  version-pr:
 804	    runs-on: ubuntu-latest
 805	    permissions: {contents: write, pull-requests: write}
 806	    steps:
 807	      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
 808	        with: {fetch-depth: 0, persist-credentials: false}
 809	      - uses: orin-dx/callisto/.github/actions/callisto-action@__COMMIT__ # callisto@__VERSION__
 810	        with: {mode: version-pr, branch: __BRANCH__}
 811	        env:
 812	          GH_TOKEN: ${{ github.token }}
 813	
 814	  plan:
 815	    runs-on: ubuntu-latest
 816	    permissions: {contents: read}
 817	    outputs:
 818	      release: ${{ steps.decision.outputs.release }}
 819	      matrix: ${{ steps.matrix.outputs.matrix }}
 820	      has_napi: ${{ steps.matrix.outputs.has_napi }}
 821	      has_artifacts: ${{ steps.matrix.outputs.has_artifacts }}
 822	    steps:
 823	      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
 824	        with: {fetch-depth: 0, persist-credentials: false}
 825	      # Content precondition, not release detection: `release plan` requires this commit to write its decision.
 826	      - name: Check for a release decision
 827	        id: decision
 828	        run: |
 829	          set -euo pipefail
 830	          release=false
 831	          if git rev-parse --verify --quiet HEAD^ > /dev/null &&
 832	            git diff-tree --no-commit-id --name-only --diff-filter=AM -r HEAD^ HEAD | grep -qxF .callisto/release-decision.json; then
 833	            release=true
 834	          fi
 835	          echo "release=$release" >> "$GITHUB_OUTPUT"
 836	      - if: steps.decision.outputs.release == 'true'
 837	        uses: orin-dx/callisto/.github/actions/setup-callisto@__COMMIT__ # callisto@__VERSION__
 838	        with: {version: callisto@__VERSION__}
 839	      - name: Plan the release
 840	        if: steps.decision.outputs.release == 'true'
 841	        run: |
 842	          set -euo pipefail
 843	          mkdir -p "$RUNNER_TEMP/release-intent"
 844	          callisto release plan --from-release-commit "$GITHUB_SHA" --decision .callisto/release-decision.json \
 845	            --orchestration-revision "$GITHUB_SHA" --artifact-repository "$GITHUB_REPOSITORY" \
 846	            --out "$RUNNER_TEMP/release-intent/release-intent.json"
 847	      - name: Build the matrix from napi targets and artifact slots
 848	        id: matrix
 849	        if: steps.decision.outputs.release == 'true'
 850	        run: |
 851	          set -euo pipefail
 852	          report="$RUNNER_TEMP/matrix.json"
 853	          callisto --format json matrix > "$report"
 854	          napi=$(jq -c '[.platformTargets[] | select(.kind=="napi") | .targets[] | {kind: "napi"} + .]' "$report")
 855	          slots=$(jq -c --slurpfile report "$report" '[.artifactSlots[] as $slot
 856	            | ([$report[0].platformTargets[] | select(.kind=="cargo") | .targets[]
 857	                | select(.artifactName == $slot.assetName and .triple == $slot.platform)] | first
 858	              // error("callisto matrix has no entry for artifact slot \($slot.assetName)"))
 859	            | {kind: "cargo"} + .]' "$RUNNER_TEMP/release-intent/release-intent.json")
 860	          {
 861	            echo "matrix=$(jq -cn --argjson napi "$napi" --argjson slots "$slots" '$napi + $slots')"
 862	            echo "has_napi=$(jq 'length > 0' <<< "$napi")"
 863	            echo "has_artifacts=$(jq 'length > 0' <<< "$slots")"
 864	          } >> "$GITHUB_OUTPUT"
 865	      - if: steps.decision.outputs.release == 'true'
 866	        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
 867	        with:
 868	          name: release-intent
 869	          path: ${{ runner.temp }}/release-intent
 870	          if-no-files-found: error
 871	
 872	  build:
 873	    needs: plan
 874	    if: needs.plan.outputs.release == 'true' && needs.plan.outputs.matrix != '[]'
 875	    strategy:
 876	      fail-fast: false
 877	      matrix:
 878	        include: ${{ fromJSON(needs.plan.outputs.matrix) }}
 879	    runs-on: ${{ matrix.hostRunner }}
 880	    permissions: {contents: read, id-token: write, attestations: write}
 881	    env:
 882	      KIND: ${{ matrix.kind }}
 883	      TRIPLE: ${{ matrix.triple }}
 884	      USE_CROSS: ${{ matrix.useCross }}
 885	      PACKAGE_DIR: ${{ matrix.packageDir }}
 886	      PACKAGE: ${{ matrix.packageName }}
 887	      MANIFEST_PATH: ${{ matrix.manifestPath }}
 888	      ASSET: ${{ matrix.artifactName }}
 889	    steps:
 890	      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
 891	        with: {persist-credentials: false}
 892	      - name: Install the Rust target
 893	        run: |
 894	          set -euo pipefail
 895	          rustup target add "$TRIPLE"
 896	          if [[ "$USE_CROSS" == true ]]; then cargo install cross --locked --version 0.2.5; fi
 897	      - name: Build the napi addon
 898	        if: matrix.kind == 'napi'
 899	        run: |
 900	          set -euo pipefail
 901	          args=(--platform --release --target "$TRIPLE" --output-dir "$RUNNER_TEMP/napi-out")
 902	          if [[ "$USE_CROSS" == true ]]; then args+=(--use-cross); fi
 903	          if [[ -n "$MANIFEST_PATH" ]]; then args+=(--manifest-path "$GITHUB_WORKSPACE/$MANIFEST_PATH"); fi
 904	          (cd "${PACKAGE_DIR:-.}" && npx --yes --package @napi-rs/cli@3.10.4 napi build "${args[@]}")
 905	      - if: matrix.kind == 'napi'
 906	        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
 907	        with:
 908	          name: napi-${{ matrix.artifactName }}
 909	          path: ${{ runner.temp }}/napi-out/*.node
 910	          if-no-files-found: error
 911	      - name: Build and archive the release artifact
 912	        if: matrix.kind == 'cargo'
 913	        run: |
 914	          set -euo pipefail
 915	          cargo_bin=cargo
 916	          if [[ "$USE_CROSS" == true ]]; then cargo_bin=cross; fi
 917	          "$cargo_bin" build --release --locked --target "$TRIPLE" --package "$PACKAGE"
 918	          metadata=$(cargo metadata --no-deps --format-version 1)
 919	          target_dir=$(jq -r .target_directory <<< "$metadata")
 920	          temp=$RUNNER_TEMP
 921	          if command -v cygpath > /dev/null; then target_dir=$(cygpath -u "$target_dir"); temp=$(cygpath -u "$temp"); fi
 922	          case "$TRIPLE" in *windows*) suffix=.exe ;; wasm32-*) suffix=.wasm ;; *) suffix= ;; esac
 923	          stage="$temp/release-stage"
 924	          out="$temp/release-assets"
 925	          mkdir -p "$stage" "$out"
 926	          jq -r --arg package "$PACKAGE" '.packages[] | select(.name == $package) | .targets[]
 927	            | select(.kind | index("bin")) | .name' <<< "$metadata" | while IFS= read -r bin; do
 928	            cp "$target_dir/$TRIPLE/release/$bin$suffix" "$stage/"
 929	          done
 930	          if [[ -z "$(ls -A "$stage")" ]]; then
 931	            echo "::error::$PACKAGE builds no binary target for $TRIPLE"
 932	            exit 1
 933	          fi
 934	          cd "$stage"
 935	          case "$ASSET" in
 936	            *.tar.gz | *.tgz) tar -czf "$out/$ASSET" ./* ;;
 937	            *.tar.xz) tar -cJf "$out/$ASSET" ./* ;;
 938	            *.zip) if command -v zip > /dev/null; then zip -q "$out/$ASSET" ./*; else 7z a -bd "$out/$ASSET" ./* > /dev/null; fi ;;
 939	            *)
 940	              binaries=(./*)
 941	              if [[ ${#binaries[@]} -ne 1 ]]; then
 942	                echo "::error::$ASSET is not an archive name, but $PACKAGE builds ${#binaries[@]} binaries"
 943	                exit 1
 944	              fi
 945	              cp "${binaries[0]}" "$out/$ASSET"
 946	              ;;
 947	          esac
 948	      - if: matrix.kind == 'cargo'
 949	        uses: actions/attest-build-provenance@4d101475d8b20a2381f78447822ac1eab6504dd8 # v4.2.2
 950	        with:
 951	          subject-path: ${{ runner.temp }}/release-assets/${{ matrix.artifactName }}
 952	      - if: matrix.kind == 'cargo'
 953	        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
 954	        with:
 955	          name: asset-${{ matrix.artifactName }}
 956	          path: ${{ runner.temp }}/release-assets/${{ matrix.artifactName }}
 957	          if-no-files-found: error
 958	
 959	  execute:
 960	    needs: [plan, build]
 961	    # A skipped build blocks only when the matrix had entries to build.
 962	    if: >-
 963	      !cancelled() && needs.plan.outputs.release == 'true' &&
 964	      (needs.build.result == 'success' || (needs.build.result == 'skipped' && needs.plan.outputs.matrix == '[]'))
