 966	    concurrency: {group: callisto-release-execute, cancel-in-progress: false}
 967	    permissions: {contents: write, id-token: write, attestations: read}
 968	    steps:
 969	      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
 970	        with: {fetch-depth: 0} # zizmor: ignore[artipacked] tag push needs persisted credentials
 971	      - uses: orin-dx/callisto/.github/actions/setup-callisto@__COMMIT__ # callisto@__VERSION__
 972	        with: {version: callisto@__VERSION__}
 973	      # Downloads land under $RUNNER_TEMP: `release execute` requires a clean worktree.
 974	      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
 975	        with:
