 980	        with:
 981	          pattern: napi-*
 982	          merge-multiple: true
 983	          path: ${{ runner.temp }}/napi-artifacts
 984	      - name: Place napi artifacts
 985	        if: needs.plan.outputs.has_napi == 'true'
 986	        run: |
 987	          set -euo pipefail
 988	          callisto --format json matrix \
 989	            | jq -r '[.platformTargets[] | select(.kind=="napi") | .targets[].packageDir] | unique[]' \
 990	            | while IFS= read -r dir; do
 991	              npx --yes --package @napi-rs/cli@3.10.4 napi artifacts --cwd "${dir:-.}" --output-dir "$RUNNER_TEMP/napi-artifacts"
 992	            done
 993	      - if: needs.plan.outputs.has_artifacts == 'true'
 994	        uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
 995	        with:
 996	          pattern: asset-*
 997	          merge-multiple: true
 998	          path: ${{ runner.temp }}/release-assets
