1017	/// Resolves `callisto@<version>`'s commit SHA on `orin-dx/callisto`'s remote.
1018	///
1019	/// GitHub's runner splits a `uses:` reference at the LAST `@` in the whole
1020	/// string (`ActionManifestManagerWrapper.ParseActionReference` in
1021	/// `actions/runner`), so a ref that itself contains `@` -- like the
1022	/// `callisto@<version>` tag this project releases under -- can never be
1023	/// written directly as `owner/repo/path@callisto@<version>`: the split lands
1024	/// inside the ref, not before it, and resolution fails. The generated
1025	/// workflow pins to this tag's resolved commit instead, like every other
1026	/// external action reference in this repository.
1027	///
1028	/// # Errors
1029	///
1030	/// The remote is unreachable, or `callisto@<version>` is not a published tag.
1031	pub fn resolve_release_commit<R: CommandRunner>(runner: &R, root: &Path, version: &str) -> Result<String, GraphError> {
1032	    const ENDPOINT: &str = "https://github.com/orin-dx/callisto.git";
1033	    let reference = format!("refs/tags/callisto@{version}");
1034	    // The peeled ref resolves an annotated tag to its commit; a lightweight
1035	    // tag has no peeled line, and its own SHA already is the commit.
1036	    let peeled = format!("{reference}^{{}}");
1037	    // A transport-level failure (git not found, timed out, ...) keeps its
1038	    // real cause via `GraphError::Command`; only a clean run that still
1039	    // can't find the tag becomes `InitWorkflowVersionUnresolved`.
1040	    let output = runner.run_quiet(
1041	        programs::GIT,
1042	        &["ls-remote", ENDPOINT, &reference, &peeled],
1043	        root,
1044	        timeouts::GIT_LS_REMOTE,
1045	    )?;
1046	    let unresolved = || GraphError::InitWorkflowVersionUnresolved {
1047	        version: version.to_owned(),
1048	    };
1049	    if output.exit_code != Some(0) {
1050	        return Err(unresolved());
1051	    }
1052	    let mut tag_object = None;
1053	    let mut commit = None;
1054	    for line in output.stdout.lines() {
1055	        let Some((sha, found)) = line.split_once('\t') else {
1056	            continue;
1057	        };
1058	        match found.trim() {
1059	            found if found == peeled => commit = Some(sha.trim().to_owned()),
1060	            found if found == reference => tag_object = Some(sha.trim().to_owned()),
1061	            _ => {}
1062	        }
1063	    }
1064	    commit.or(tag_object).ok_or_else(unresolved)
1065	}
