use callisto_model::{CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, MatrixReport, PackageId};

use crate::error::GraphError;
use crate::matrix::{
    add_release_artifact_groups, build_matrix_report, MatrixPackageInput, NapiCrate, ReleaseArtifactInput,
};
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct MatrixOptions {
    /// When Some, restrict the report to exactly this one registered package.
    /// Accepts a bare name -- resolved only when it matches exactly one
    /// registered package (`GraphError::AmbiguousName` otherwise, listing
    /// the qualified candidates) -- or an ecosystem-qualified id
    /// (`cargo/foo`, `npm/foo`). Err(GraphError::UnknownPackage) when no
    /// registered package matches. Resolved through
    /// [`crate::IdentityIndex::resolve`], the one selector resolver shared
    /// with every other package-selecting surface.
    pub package: Option<String>,
    /// Resolve each napi package's addon crate into `manifestPath` (E204 when not exactly one).
    pub napi_crates: bool,
}

pub fn matrix<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    opts: &MatrixOptions,
) -> Result<MatrixReport, GraphError> {
    let all_packages: Vec<&callisto_model::Package> = ws.graph.packages().collect();

    let selected = opts
        .package
        .as_deref()
        .map(|raw| resolve_selected_package(&all_packages, &ws.identity, raw))
        .transpose()?;

    let inputs: Vec<MatrixPackageInput> = all_packages
        .iter()
        .filter(|p| selected.as_ref().is_none_or(|id| p.id == *id))
        .map(|p| {
            let dir_rel = package_dir_rel(p);
            MatrixPackageInput {
                id: p.id.clone(),
                dir_abs: ws.root.join(&dir_rel),
                dir_rel,
                name: p.id.name().to_string(),
            }
        })
        .collect();

    let napi_crates = opts
        .napi_crates
        .then(|| workspace_napi_crates(ws, &all_packages))
        .transpose()?;
    let mut report = build_matrix_report(&inputs, napi_crates.as_deref())?;
    let mut artifacts = Vec::new();
    for artifact in ws
        .config
        .product_release
        .iter()
        .flat_map(|release| &release.artifacts)
        .filter(|artifact| artifact.package.ecosystem() == Some(callisto_model::Ecosystem::Cargo))
        .filter(|artifact| {
            selected
                .as_ref()
                .is_none_or(|id| ws.identity.identifies(&artifact.package, id))
        })
    {
        let resolved = all_packages.iter().find_map(|package| {
            let manifest = package
                .canonical_manifests()
                .find(|manifest| manifest.ecosystem() == callisto_model::Ecosystem::Cargo)?;
            ws.identity
                .identifies(&artifact.package, &package.id)
                .then_some((package, manifest))
        });
        let Some((package, manifest)) = resolved else {
            report.diagnostics.push(Diagnostic {
                code: DiagnosticCode::UnknownPackage,
                severity: DiagnosticSeverity::Warning,
                message: format!(
                    "`[[release.artifact]]` package `{}` (asset `{}`) is not a cargo package in this workspace; it has no matrix entry",
                    artifact.package, artifact.asset_name
                ),
                package: Some(artifact.package.clone()),
                path: None,
                escalated_by: None,
                governed_by: None,
            });
            continue;
        };
        artifacts.push(ReleaseArtifactInput {
            id: package.id.clone(),
            name: package.id.name().to_string(),
            dir_rel: manifest
                .path
                .parent()
                .map(|dir| dir.to_string_lossy().to_string())
                .unwrap_or_default(),
            target: artifact.target.clone(),
            asset_name: artifact.asset_name.clone(),
        });
    }
    add_release_artifact_groups(&mut report, &artifacts)?;
    Ok(report)
}

/// Resolves a human-typed `--package` argument (bare or ecosystem-qualified)
/// through the one selector resolver, [`crate::IdentityIndex::resolve`] --
/// a bare name is accepted only when it names exactly one package.
fn resolve_selected_package(
    all_packages: &[&callisto_model::Package],
    identity: &crate::IdentityIndex,
    raw: &str,
) -> Result<PackageId, GraphError> {
    let resolved = identity.resolve(raw)?;
    if all_packages.iter().any(|p| p.id == resolved) {
        Ok(resolved)
    } else {
        Err(GraphError::UnknownPackage { id: resolved })

    /// Resolves `name` (qualified or bare) to a binary-producing package.
    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
        let invalid = |reason| GraphError::InitInvalidProductPackage {
            package: name.to_owned(),
            reason,
            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
        };
        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
            Some(package) => vec![package],
            None => self.packages.iter().filter(|package| package.name() == name).collect(),
        };
        match found.as_slice() {
            [package] if package.is_binary() => Ok(package),
            [_] => Err(invalid("it does not produce a binary artifact")),
            _ => Err(invalid("it is not a workspace package")),
        }
    }
}

/// Opt-in to shipping binaries as GitHub release assets.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BinaryRelease {
    /// Qualified id of the product package.
    pub product: String,
    pub forge_repository: GitHubRepository,
    pub targets: Vec<String>,
}

/// The operator's intent; everything else is detected.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InitAnswers {
    pub versioning: Versioning,
    pub binaries: Option<BinaryRelease>,
}

fn io_err(path: &Path) -> impl Fn(std::io::Error) -> GraphError + '_ {
    move |error| GraphError::InitIo {
        path: path.to_path_buf(),
        message: error.to_string(),
    }
}

fn ensure_uninitialized(root: &Path) -> Result<(), GraphError> {
    let path = root.join("callisto.toml");
    if path.exists() {
        return Err(GraphError::InitAlreadyInitialized { path });
    }
    Ok(())
}

fn qualified_id(package: &callisto_model::Package) -> String {
    match package.canonical_manifests().next() {
        Some(manifest) => format!("{}/{}", manifest.ecosystem().prefix(), package.id.name()),
        None => package.id.display_name(),
    }
}

/// Detects the workspace facts `init` reports and builds on.
///
/// # Errors
///
/// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
/// ambiguous tag convention.
pub fn detect<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
) -> Result<InitFacts, GraphError> {
    let root = canonical_root(root)?;
    ensure_uninitialized(&root)?;
    let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
    if git_dir.exit_code != Some(0) {
        return Err(GraphError::InitNotGitRepository { root });
    }
    let origin = optional_git_remote(&root, runner)?;

